import{_ as a,o as t,c as o,a7 as n}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Spendzo Data Deletion","description":"Standalone data-deletion instructions for the Spendzo application.","frontmatter":{"title":"Spendzo Data Deletion","description":"Standalone data-deletion instructions for the Spendzo application.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/spendzo.md","filePath":"data-deletion/spendzo.md"}'),l={name:"data-deletion/spendzo.md"};function s(i,e,r,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="delete-spendzo-data" tabindex="-1">Delete Spendzo Data <a class="header-anchor" href="#delete-spendzo-data" aria-label="Permalink to &quot;Delete Spendzo Data&quot;">​</a></h1><p>Spendzo has no user account or server-side data. Your app data is stored locally on your device.</p><h2 id="delete-individual-expenses" tabindex="-1">Delete individual expenses <a class="header-anchor" href="#delete-individual-expenses" aria-label="Permalink to &quot;Delete individual expenses&quot;">​</a></h2><p>Open Spendzo, select the relevant transaction, choose <strong>Delete</strong>, and confirm.</p><h2 id="delete-all-app-data" tabindex="-1">Delete all app data <a class="header-anchor" href="#delete-all-app-data" aria-label="Permalink to &quot;Delete all app data&quot;">​</a></h2><p>Use either of these Android options:</p><ol><li>Open <strong>Settings &gt; Apps &gt; Spendzo &gt; Storage</strong> and select <strong>Clear storage</strong> or <strong>Clear data</strong>.</li><li>Uninstall Spendzo.</li></ol><p>Clearing storage or uninstalling removes Spendzo&#39;s app-private local database, settings, PIN verifier, and biometric unlock material from that installation.</p><h2 id="delete-exported-files" tabindex="-1">Delete exported files <a class="header-anchor" href="#delete-exported-files" aria-label="Permalink to &quot;Delete exported files&quot;">​</a></h2><p>Backups, CSV files, and PDF files saved through Android&#39;s document picker are outside Spendzo&#39;s private storage. Delete those files separately using the file manager or storage provider where you saved them.</p><p>There is no server deletion request to submit because Spendzo does not upload or retain user data. For help, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',11)])])}const u=a(l,[["render",s]]);export{h as __pageData,u as default};
